# Windows PowerShell Script for ASP.NET Core Setup Write-Host "========================================" -ForegroundColor Cyan Write-Host " Starting ASP.NET Core Environment Setup" -ForegroundColor Cyan Write-Host "========================================" -ForegroundColor Cyan if (Test-Path ".env.example") { Copy-Item ".env.example" -Destination ".env" Write-Host "[SUCCESS] Configuration file (.env) generated." -ForegroundColor Green } else { Write-Host "[ERROR] Template file not found!" -ForegroundColor Red }